#!/usr/bin/env bash
# Writes game_ref.inc: the racing_game a8a1b13 functions the g2m_world tests pin
# against, extracted VERBATIM by line range from the commit (not the working
# tree). Usage: extract_game_ref.sh <racing_game checkout> <out game_ref.inc>
# Then build refgen (see tests/world/CMakeLists.txt, option G2M_WORLD_REFGEN)
# and run it; its output holds the pinned hashes in test_*.cpp.
set -euo pipefail
GAME="$1"
OUT="$2"
REV=a8a1b13
show() { git -C "$GAME" show "$REV:$1"; }
{
  cat <<'EOF'
// Verbatim extraction of racing_game a8a1b13 (generated by extract_game_ref.sh).
#include "g2m/layer/height_tile.h"
#include "g2m/layer/layer_id.h"
#include "g2m/layer/osm_roads.h"
#include "g2m/layer/src_osm.h"
#include "g2m/layer/terrain_layers.h"
#include "g2m/layer/tile_container.h"
#include "g2m/server/protocol.h"
#include <algorithm>
#include <cmath>
#include <functional>
#include <limits>
#include <map>
#include <memory>
#include <mutex>
#include <optional>
#include <span>
#include <string_view>
namespace rg {
using L0TileLookupFn = std::function<const g2m::HeightTile*(const g2m::TileKey&)>;
EOF
  show core/include/rg/world_terrain.h | sed -n '127,131p;155p;185,199p;220p'   # HeightTileFetchResult, HeightTileFetchFn, RoadFetchStatus, RoadSegmentsResult, RoadSegmentsFetchFn
  show core/src/world_terrain.cpp | sed -n '511,581p;665,742p'                   # decode_height_tile_container, fetch_height_tile_cached, decode_road_segments_response, fetch_road_segments_cached
  show core/src/route_check.cpp | sed -n '444,491p'                               # sample_l0_height
  echo "} // namespace rg"
} > "$OUT"
